import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Part 5 — UML & Design Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_05_UML.md","filePath":"todo/study_plan/parts/Part_05_UML.md"}'),i={name:"todo/study_plan/parts/Part_05_UML.md"};function r(s,t,n,l,c,m){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="part-5-—-uml-design-documentation" tabindex="-1">Part 5 — UML &amp; Design Documentation <a class="header-anchor" href="#part-5-—-uml-design-documentation" aria-label="Permalink to &quot;Part 5 — UML &amp; Design Documentation&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 3 (light pass alongside Part 4). <strong>Budget: ~2 hrs.</strong></p></blockquote><h2 id="_5-uml-design-documentation-—-topic-inventory" tabindex="-1">5 UML &amp; Design Documentation — topic inventory <a class="header-anchor" href="#_5-uml-design-documentation-—-topic-inventory" aria-label="Permalink to &quot;5 UML &amp; Design Documentation — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Class diagram — relationships (association, aggregation, composition, inheritance, dependency)</td><td>🔴 💼 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📖 Refactoring Guru — &quot;UML class diagram&quot; quick ref (~20 min)</td></tr><tr><td>2</td><td>Sequence diagram — for any flow with &gt; 2 services</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>State diagram — perfect for KYC status, order state, etc.</td><td>🔴 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>4</td><td>Activity diagram</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>5</td><td>Component diagram</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>Deployment diagram — infra-level</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>7</td><td>C4 model — Context, Container, Component, Code (modern alternative)</td><td>🟠 💼 🆕</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📖 c4model.com — official intro (~30 min)</td></tr><tr><td>8</td><td>Tooling — PlantUML, Mermaid (Markdown-native), draw.io, Excalidraw</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>🎓 Mermaid live editor — try sequence/state/class examples</td></tr><tr><td>9</td><td>Use case diagram</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>ER diagram</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>11</td><td>Object diagram, package diagram</td><td>🟢</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~3.75 hrs</td><td>~0.3 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~8.5 hrs</td><td>~0.8 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡 + 🟢)</td><td>~10.75 hrs</td><td>~1 wk</td><td></td></tr></tbody></table><blockquote><p>Short Part. Practical use matters more than theoretical fluency — draw 2-3 diagrams of your real KYC platform as the deliverable.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Association vs Aggregation vs Composition — distinguish with concrete examples. <ul><li><strong>Why asked:</strong> Most-confused trio in UML. Association = generic &quot;uses&quot; relationship (Employee uses Computer). Aggregation = whole-part with independent lifetimes (Department has Employees, but Employees outlive Department). Composition = whole-part with bound lifetimes (Order owns OrderItems, OrderItems die with Order). Arrowheads differ: line / open diamond / filled diamond.</li></ul></li><li><strong>Q:</strong> When do you reach for sequence diagram vs state diagram vs activity diagram? <ul><li><strong>Why asked:</strong> Tests diagram judgment. Sequence = inter-service interactions over time, lifelines + messages. State = single entity&#39;s lifecycle, states + transitions. Activity = workflow / business process, swim lanes + decisions. Pick by what question you&#39;re answering.</li></ul></li><li><strong>Q:</strong> What&#39;s the C4 model and how does it differ from traditional UML? <ul><li><strong>Why asked:</strong> Modern alternative gaining traction. C4 = 4 nested zoom levels: Context (system in its env), Container (apps/databases), Component (modules inside containers), Code (classes — usually skipped). Strengths over UML: simpler vocabulary, opinionated about levels, less notation overhead, prescribes audience per level.</li></ul></li><li><strong>Q:</strong> Walk through how you&#39;d diagram the KYC verification flow for a new joiner. Which diagram types, in what order? <ul><li><strong>Why asked:</strong> Tests practical communication skill. Likely answer: (1) C4 Container diagram showing SDK → orchestrator → vendors; (2) Sequence diagram showing one verification end-to-end; (3) State diagram of the KYC status machine. Top-down zoom-in pattern.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Open diamond vs filled diamond — what&#39;s the actual semantic difference in code? <ul><li><strong>Gotcha:</strong> Open (aggregation) = &quot;has-a&quot; with shared lifecycle. The parts can exist without the whole. Filled (composition) = &quot;owns&quot; — when the whole is destroyed, parts must be destroyed too. In Java/Spring terms: composition often implies the parent is responsible for creating + destroying the child. Most &quot;uses&quot; relationships are actually association (plain line) — UML over-uses diamonds.</li></ul></li><li><strong>Q:</strong> What does a dashed line arrow in a class diagram mean? <ul><li><strong>Gotcha:</strong> Dependency — class A <em>uses</em> class B (e.g., as a method parameter or local variable) but doesn&#39;t store B as a field. Solid line = stronger relationship (association: stores reference). Easy to confuse.</li></ul></li><li><strong>Q:</strong> In a state diagram, what&#39;s the difference between a guard <code>[x &gt; 5]</code> and an action <code>/ doSomething()</code>? <ul><li><strong>Gotcha:</strong> Guard appears in square brackets on the transition, evaluated to decide IF the transition fires. Action appears after a slash, executed WHEN the transition fires. Many state diagrams omit guards entirely — a common error.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>State diagram of the KYC status machine</strong> (~2 hrs) — directly your platform. Diagram IN_PROGRESS / VERIFIED / REVIEW / ERROR / FAILED + the transitions, guards, and entry/exit actions. Becomes a portable artifact for design discussions + STAR stories.</li><li><strong>C4 Container + Component diagrams of the KYC orchestrator</strong> (~2.5 hrs) — your platform documented in modern style. Useful for senior interviews when asked &quot;design a KYC platform.&quot;</li><li><strong>Sequence diagram of a verification flow end-to-end</strong> (~1.5 hrs) — SDK launch → backend → 3 vendor calls → status callback → partner notification. Practice rendering complex multi-service flows.</li></ul><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Association arrowhead types — quick ref.</strong> A. Plain line = association. Open arrow = directed association. Open diamond = aggregation (loose has-a). Filled diamond = composition (owns, dies-with). Dashed arrow = dependency (uses, doesn&#39;t store). Triangle arrow (hollow) = generalization / inheritance.</p><p><strong>Q. Aggregation vs composition — one-line distinction.</strong> A. Aggregation: parts outlive the whole. Composition: parts die with the whole. Composition implies stronger ownership in code (creation + destruction responsibility).</p><p><strong>Q. State diagram: <code>event [guard] / action</code> — what&#39;s each piece?</strong> A. Event triggers the transition. Guard is a boolean precondition (transition only fires if true). Action is executed when transition fires. Inside a state, you can also have entry/exit actions and do-activities.</p><p><strong>Q. C4 model levels in order from outside-in.</strong> A. Context (system + external actors) → Container (apps + databases inside the system) → Component (modules inside a container) → Code (classes inside a component — usually skipped because UML class diagrams cover it).</p>',18)])])}const g=e(i,[["render",r]]);export{u as __pageData,g as default};
